from time import sleep
from taf.sbts.oam.coam.admin import admin
from taf.internal.sbts.admin.exceptions import AdminApiProcedureFailureException
from taf.config.scf import scf
from taf.rfrl.l3_call.logger.l3_call_logger import log_operation, log_to_console
from taf.rfrl.l3_call.cell.exceptions import ParameterNotFound
from taf.rfrl.l3_call.cell.cell import Cell


class ClassicalCell(Cell):
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self, cell_distname, bts_connection_alias, shared_spectrum):
        super(ClassicalCell, self).__init__(cell_distname, shared_spectrum)
        self._connection = bts_connection_alias
        self._api = admin()
        self._scf = scf()
        self._managed_object_class_name = ""

    @property
    def managed_object_class_name(self):
        """
        Returns name of managed object class for cell_type
        """
        if not self._managed_object_class_name:
            self._managed_object_class_name = self._get_managed_object_class_name()

        return self._managed_object_class_name

    def get_spectrum(self, cells_info, cell_specific_info):
        """
        Calculates lower and upper limit of cell spectrum

        :return: list where first element is lower limit of frequency
        and second element is upper limit of frequency
        :rtype: list(float)
        """
        channel_bandwidth, carrier_frequency = self._get_carrier_frequency_and_channel_bandwidth(
            cells_info=cells_info,
            cell_specific_info=cell_specific_info)

        lower_frequency = carrier_frequency - 0.5 * channel_bandwidth
        upper_frequency = carrier_frequency + 0.5 * channel_bandwidth

        return [lower_frequency, upper_frequency]

    def _is_dss(self):
        return True if self._get_dss_pair() else False

    def _get_configuration_distname_using_physical_cell_id(self, physical_cell_id, cell_type):
        cells_info = self._api.get_cells_info(connection=self._connection, cell_type=cell_type)

        for cell_info in cells_info:
            if int(cell_info["physicalCellId"]) == int(physical_cell_id):
                return cell_info["id"]["configuration"]

        raise ParameterNotFound("Could not find configuration distname for cell "
                                "with physicalCellId: {}".format(physical_cell_id))

    def _get_physical_cell_id_using_configuration_distname(self, configuration_distname, cell_type):
        cells_info = self._api.get_cells_info(connection=self._connection, cell_type=cell_type)

        for cell_info in cells_info:
            if cell_info["id"]["configuration"] == configuration_distname:
                return cell_info["physicalCellId"]

        raise ParameterNotFound("Could not find physicalCellId for cell "
                                "with configuration distname: {}".format(configuration_distname))

    def _get_configuration_distname_using_cell_id(self, cell_id, cell_type):
        cells_info = self._api.get_cells_info(connection=self._connection, cell_type=cell_type)

        for cell_info in cells_info:
            if cell_info["id"]["configuration"].split("/")[-1].split("-")[-1] == cell_id:
                return cell_info["id"]["configuration"]

        raise ParameterNotFound("Could not find configuration distname for cell "
                                "with ID: {}".format(cell_id))

    def _change_cellbarred_parameter(self, value, cell_distname):
        log_operation("Changing cellBarred parameter value to '{}' for {}".format(value, cell_distname))
        for _ in range(4):
            try:
                self._api.perform_parameter_recommissioning(connection=self._connection,
                                                            skip_parameter_relation_errors=True,
                                                            dist_name=cell_distname,
                                                            parameter='cellBarred',
                                                            value=value,
                                                            operation='update')
                break
            except AdminApiProcedureFailureException as e:
                log_to_console("Failed to change cellBarred parameter value to '{}' "
                               "for {} with error: {} \n !!TRYING AGAIN!!".format(value, cell_distname, e))
                sleep(60)  # reason: SISOCRT-2441

    def _block_cell(self, timeout=60):
        log_operation("Blocking cell with distname {}".format(self.distname))
        self._api.block_cell(dist_name=self.distname, connection=self._connection, timeout=timeout)

    def _unblock_cell(self, timeout=60):
        log_operation("Unblocking cell with distname {}".format(self.distname))
        self._api.unblock_cell(dist_name=self.distname, connection=self._connection, timeout=timeout)

    def _check_blocking_state(self, expected_state):
        blocking_state = self._api.get_cell_specific_info(cell_id=self.distname,
                                                          connection=self._connection)['status']['blockingState']
        return blocking_state == expected_state

    def _get_managed_object_class_name(self):
        cell = self.distname.split("/")[-1].split("-")[0]
        return "NRCEL" if cell == "NRCELL" else cell

    def _get_cell_technology(self):
        return self._api.get_parameters_for(class_name=self.managed_object_class_name,
                                            id_num=self._get_cell_runtime_distname(),
                                            connection=self._connection)["technology"]

    def _get_narrowband_iot_mode(self, timeout=30):
        cells_info = self._api.get_cells_info(cell_type=self._type, connection=self._connection, timeout=timeout)

        for cell in cells_info:
            if cell["id"]["configuration"] == self.distname:
                return cell.get('narrowbandIotMode')

        raise ParameterNotFound("Could not find narrowbandIotMode for cell with confifuration distname: {} "
                                "Please check if given configuration distname is correct!".format(self.distname))

    def _get_cell_runtime_distname(self, timeout=30):
        cells_info = self._api.get_cells_info(cell_type=self._type, connection=self._connection, timeout=timeout)

        for cell in cells_info:
            if cell["id"]["configuration"] == self.distname:
                return cell["id"]["internal"]

        raise ParameterNotFound("Could not find runtime distname for cell with confifuration distname: {} "
                                "Please check if given configuration distname is correct!".format(self.distname))

    def _load_scf(self):
        local_dir_path = "/tmp/scf/"
        file_name = "SCF_{}.xml".format(self._configuration_id)
        self._api.get_current_scf_file(local_dir_path=local_dir_path, file_name=file_name,
                                       export_type="configurationAndRuntimeObjects", timeout=30,
                                       connection=self._connection)
        self._scf.load_scf(local_dir_path + file_name)

    def _get_channel_bandwidth(self, cell_specific_info):
        try:
            channel_bandwidth = cell_specific_info["downlinkChannelBandwidth"]
        except KeyError:
            channel_bandwidth = cell_specific_info["channelBandwidth"]
        return channel_bandwidth

    def _get_carrier_frequency_and_channel_bandwidth(self, cells_info, cell_specific_info):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_carrier_frequency_and_channel_bandwidth.__name__))
